use anyhow::{ensure,Result};
use glam::{Mat4,Vec3};
use crate::{Prepared,log::{Log,root},gpu::Gpu,scene::{Scene,TABLE,PIXEL}};
pub fn run(log:&Log,prepared:Prepared)->Result<()>{let mut gpu=Gpu::new(log,None,0xb000)?;let mut scene=Scene::new(prepared.source,prepared.assets,&mut gpu)?;scene.show_hud=false;scene.playing=false;let(texture,target)=gpu.offscreen(1200,900)?;let projection=Mat4::perspective_rh(42f32.to_radians(),1200.0/900.0,0.01,40.0);let mut cases=Vec::new();
 for(kind,team)in[("minion",0),("minion",1),("tower",0),("tower",1),("champion",0)]{let mut found=None;for tick in 0..=scene.source.manifest().result.ticks{let f=scene.source.frame(tick);for e in &f.projectile_kinds{if e.2!=0{continue;}let Some(m)=scene.source.manifest().catalog.get(&(e.1+1))else{continue;};if m.kind!=kind||(kind=="champion"&&m.name!="soldier"){continue;}if let Some(p)=f.projectiles.iter().find(|p|p.0==e.0&&p.3==e.1&&p.4==team){found=Some((tick,*p));break;}}if found.is_some(){break;}}
  let Some((tick,row))=found else{cases.push(serde_json::json!({"kind":kind,"team":team,"관측":"이번 경기에서 해당 사례 없음"}));continue;};scene.seek(tick as f64+0.5);let point=Vec3::new(((row.1*0.001-480.0)*PIXEL as f64)as f32,TABLE+0.035,((row.2*0.001-480.0)*PIXEL as f64)as f32);let head=point+Vec3::new(0.0,0.20,0.32);let view=Mat4::look_at_rh(head,point,Vec3::Y);let q=view.inverse().to_scale_rotation_translation().1;for _ in 0..12{scene.update(&mut gpu,head,q,0.1)?;}let flights=scene.projectile_snapshot();let flight=flights.iter().find(|v|v["handle"].as_u64()==Some(row.0)).unwrap();ensure!(flight["category"]==0,"원본 종류 추정 값을 바꾸면 안 됨");if kind=="champion"{ensure!(flight["fallbackGlow"]==true&&flight["npcSingleTagFallback"]==false,"챔피언 미확정 그림 대체 금지");}else{ensure!(flight["npcSingleTagFallback"]==true&&flight["fallbackGlow"]==false,"단일 태그 NPC 그림 복원 누락");let tag=if kind=="tower"{"attack_projectile"}else if team==0{"blue_projectile"}else{"red_projectile"};ensure!(flight["tag"]==tag,"단일 원본 태그 불일치");}
  let label=format!("{kind}_team{team}");gpu.mask(|_|true);gpu.render(&target,projection*view,scene.world(),true);gpu.save_png(&texture,&root().join(format!("_tmp/shots/native_ui_layout_projectile_{label}.png")))?;gpu.mask(|n|n=="projectiles");gpu.render(&target,projection*view,scene.world(),true);let(_,_,pixels)=gpu.pixels(&texture)?;let bg=&pixels[..4];let visible=pixels.chunks_exact(4).filter(|p|*p!=bg).count();ensure!(visible>0,"NPC 원본 그림 화면 기여 없음");gpu.save_png(&texture,&root().join(format!("_tmp/shots/native_ui_layout_projectile_{label}_only.png")))?;cases.push(serde_json::json!({"kind":kind,"team":team,"tick":tick,"flight":flight,"visiblePixels":visible}));
 }
 gpu.check()?;let report=serde_json::json!({"검증":"미니언·타워 단일 태그 대응 및 챔피언 미확정 유지 검사 완료","cases":cases,"근거수준":"시전자 종류/팀/유일한 원본 투사체 태그 대응. 공식 투사체 타입을 직접 읽은 것은 아님."});std::fs::write(root().join("_tmp/logs/native_ui_layout_npc_art.json"),serde_json::to_vec_pretty(&report)?)?;log.line("NPC 단일 태그 투사체 복원 검사 완료");Ok(())}
